<?php namespace App\Filament\Resources\StudentSocialPassportResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;use Illuminate\Support\Facades\DB;class StatusesRelationManager extends RelationManager{protected static string $relationship='statuses';protected static ?string $title='Социальные статусы';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('category_id')->label('Категория')->options(fn()=>DB::table('student_social_categories')->where('active',1)->orderBy('name')->pluck('name','id'))->required(),Forms\Components\DatePicker::make('valid_from')->label('С'),Forms\Components\DatePicker::make('valid_until')->label('По'),Forms\Components\TextInput::make('document_type')->label('Документ'),Forms\Components\TextInput::make('document_number')->label('Номер'),Forms\Components\Textarea::make('note')->label('Примечание')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('category_id')->label('Категория')->formatStateUsing(fn($id)=>DB::table('student_social_categories')->where('id',$id)->value('name')?:'—'),Tables\Columns\TextColumn::make('valid_from')->label('С')->date('d.m.Y'),Tables\Columns\TextColumn::make('valid_until')->label('По')->date('d.m.Y'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить статус')->mutateFormDataUsing(fn($d)=>$d+['status'=>'active','created_by'=>auth()->id()])])->actions([Tables\Actions\Action::make('close')->label('Закрыть')->visible(fn($x)=>$x->status==='active')->action(fn($x)=>$x->update(['status'=>'closed','valid_until'=>$x->valid_until?:today()]))]);}}